use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use futures::{stream, StreamExt, TryStreamExt};

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    let stopped = Arc::new(AtomicBool::new(false));

    let work = stream::iter(ids)
        .map({
            let stopped = Arc::clone(&stopped);
            move |id| {
                let fetch = fetch.clone();
                let stopped = Arc::clone(&stopped);
                async move {
                    if stopped.load(Ordering::SeqCst) {
                        return Ok::<u64, SolveError>(0);
                    }

                    match fetch.fetch(id).await {
                        Ok(value) => Ok::<u64, SolveError>(value),
                        Err(_) => {
                            stopped.store(true, Ordering::SeqCst);
                            Err(SolveError::Fetch { id })
                        }
                    }
                }
            }
        })
        .buffer_unordered(4)
        .try_fold(0u64, |sum, value| async move {
            Ok::<u64, SolveError>(sum + value)
        });

    match lgwks_bot::rt::time::timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

