//! A four-stage pipeline driven as a single future.
//!
//! `fetch_a` and `fetch_b` run concurrently; `combine` runs only after both
//! succeed; `publish` runs only after `combine`. The whole thing is bounded by
//! one overall deadline. Nothing is spawned, so dropping the returned future —
//! directly or because the timeout elapsed — drops every in-flight stage and
//! stops the work it owns.

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};

/// Failure modes of [`solve`].
#[derive(Debug)]
pub enum PipelineError {
    /// A named stage failed; no later stage was run.
    Stage { name: StageName },
    /// The overall deadline elapsed; no later stage was run.
    Deadline,
    /// The pipeline was cancelled before it could finish.
    Cancelled,
}

/// Run `fetch_a` and `fetch_b` concurrently, then `combine`, then `publish`,
/// bounded by `deadline`.
///
/// Every fallible call is handled here rather than left implicit:
/// - a fetch failure short-circuits before `combine`/`publish`,
/// - a stage error is tagged with the stage that produced it,
/// - the elapsed deadline is surfaced as [`PipelineError::Deadline`].
///
/// Cleanup is explicit: the timeout future owns the pipeline future, so on drop
/// or expiry it drops the in-flight stage future and nothing is left running.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match lgwks_bot::rt::time::timeout(deadline, drive(&stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

async fn drive(stage: &Stage) -> Result<Published, PipelineError> {
    let fetch_a = async {
        stage
            .run(StageName::FetchA)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::FetchA,
            })
    };
    let fetch_b = async {
        stage
            .run(StageName::FetchB)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::FetchB,
            })
    };

    let (_a, _b) = futures::future::try_join(fetch_a, fetch_b).await?;

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Combine,
        })?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(|_| PipelineError::Stage {
            name: StageName::Publish,
        })?;

    Ok(Published::from(published))
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use futures::future::try_join;
use futures::TryFutureExt;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async move {
        let a = stage
            .run(StageName::FetchA)
            .map_err(|_| PipelineError::Stage { name: StageName::FetchA });
        let b = stage
            .run(StageName::FetchB)
            .map_err(|_| PipelineError::Stage { name: StageName::FetchB });

        let (a, b): (Artifact, Artifact) = try_join(a, b).await?;

        let combined = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Combine })?;

        let _ = (a, b, combined);

        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage { name: StageName::Publish })?;

        Ok::<Published, PipelineError>(Published::from(published))
    };

    lgwks_bot::rt::time::timeout(deadline, work)
        .await
        .map_err(|_| PipelineError::Deadline)?
}

