                        .fetch(id)
                        .await
                        .map_err(|_| SolveError::Fetch { id })
                }
            })
            .buffer_unordered(CONCURRENCY)
            .try_collect::<Vec<u64>>()
            .await
            .map(|values| values.into_iter().sum::<u64>())
