//! Bounded-concurrency aggregation over `ai_task_support::Fetcher`.
//!
//! The whole fan-out lives inside the future returned by [`solve`]: there is no
//! `spawn` anywhere in this crate, so dropping that future drops the stream,
//! which drops every in-flight `fetch`.

use futures::{StreamExt, TryStreamExt, stream};
use std::time::Duration;

/// Contract for a set of ids whose values are being summed.
#[derive(Debug)]
pub enum SolveError {
    /// A `fetch` failed; `id` is one of the ids that failed.
    Fetch { id: u32 },
    /// The overall `deadline` elapsed before the aggregate resolved.
    Deadline,
    /// The returned future was abandoned by the caller.
    Cancelled,
}

/// The contract caps concurrency at 4, independent of how many ids there are.
const MAX_IN_FLIGHT: usize = 4;

/// Sum the value of every `id`, running at most [`MAX_IN_FLIGHT`] fetches at a time.
///
/// * Any `fetch` error resolves to `Err(SolveError::Fetch { id })`. `try_fold`
///   stops at the first `Err` and drops the stream, which cancels every fetch
///   still in flight and pulls the source, so no new fetch starts afterwards.
/// * `deadline` is enforced with `timeout`, which drops the work on elapse, so
///   the same "no further fetches" guarantee holds on the deadline path.
/// * An empty `ids` resolves to `Ok(0)`.
pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    if ids.is_empty() {
        return Ok(0);
    }

    // `buffer_unordered` is a plain bounded fan-out: it holds at most
    // `MAX_IN_FLIGHT` of these futures at any moment and frees a slot as soon
    // as one completes, so a slow fetch never blocks the others behind it.
    // Order is irrelevant here because the results are only summed.
    let work = stream::iter(ids)
        .map(|id| {
            let fetch = fetch.clone();
            async move { fetch.fetch(id).await.map_err(|_| SolveError::Fetch { id }) }
        })
        .buffer_unordered(MAX_IN_FLIGHT)
        .try_fold(0u64, |sum, value| async move { Ok(sum + value) });

    match lgwks_bot::rt::time::timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Published, Stage, StageName};

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let pipeline = async move {
        // The two fetches are independent, so start both before awaiting either.
        // Each future carries its own stage name in its error, so the first
        // failure reported by the join names the stage that actually failed.
        let fetch_a = async {
            stage
                .run(StageName::FetchA)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchA,
                })
        };
        let fetch_b = async {
            stage
                .run(StageName::FetchB)
                .await
                .map_err(|_| PipelineError::Stage {
                    name: StageName::FetchB,
                })
        };

        // On the first error the other fetch is dropped, and neither `combine`
        // nor `publish` is ever started.
        let (artifact_a, artifact_b) = futures::try_join!(fetch_a, fetch_b)?;

        // `combine` is only reached once both fetches have succeeded.
        let combined = stage
            .run(StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Combine,
            })?;

        // Keep the dependency on both fetch artifacts explicit.
        let _inputs = (artifact_a.value(), artifact_b.value());
        let _ = combined.value();

        let published = stage
            .run(StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: StageName::Publish,
            })?;

        Ok(Published::from(published))
    };

    // `timeout` owns the pipeline future: when it elapses it drops every stage
    // future inside, and when the caller drops this future the same happens, so
    // no stage keeps running in the background.
    match lgwks_bot::rt::time::timeout(deadline, pipeline).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

//! Bounded fan-out pipeline over `ai_task_support::Stage`.
//!
//! `fetch_a` and `fetch_b` run concurrently; `combine` runs only once both
//! have succeeded, and `publish` only after `combine`. The whole pipeline sits
//! under one deadline, and because nothing is ever spawned, dropping the future
//! returned by `solve` tears down whatever stage was in flight.

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};

use futures::future::try_join;

/// Failures the pipeline can report.
#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    #[allow(dead_code)]
    Cancelled,
}

/// Run a single stage, tagging any failure with the stage that produced it.
async fn run_stage(stage: &Stage, name: StageName) -> Result<Artifact, PipelineError> {
    let failed = name.clone();
    match stage.run(name).await {
        Ok(artifact) => Ok(artifact),
        Err(_) => Err(PipelineError::Stage { name: failed }),
    }
}

/// The dependency-ordered body of the pipeline, with no deadline of its own.
async fn pipeline(stage: Stage) -> Result<Published, PipelineError> {
    let (_a, _b) = try_join(
        run_stage(&stage, StageName::FetchA),
        run_stage(&stage, StageName::FetchB),
    )
    .await?;

    let _combined = run_stage(&stage, StageName::Combine).await?;
    let published = run_stage(&stage, StageName::Publish).await?;

    Ok(published.into())
}

/// Run the full pipeline under a single overall deadline.
///
/// On success the `publish` artifact is carried in the returned `Published`.
/// A failing fetch short-circuits `combine` and `publish`; elapsing the
/// deadline yields `PipelineError::Deadline` and drops the in-flight stage.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    match lgwks_bot::rt::time::timeout(deadline, pipeline(stage)).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};
use futures::TryFutureExt;
use futures::future::try_join;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Tracks the single overall deadline shared by every stage.
struct Budget {
    start: Instant,
    total: Duration,
}

impl Budget {
    fn new(total: Duration) -> Self {
        Self { start: Instant::now(), total }
    }

    /// `None` once the overall deadline has already passed.
    fn remaining(&self) -> Option<Duration> {
        self.total.checked_sub(self.start.elapsed())
    }
}

/// Runs one stage under the overall budget.
///
/// On a stage error the deadline is reported in preference only if the stage
/// itself blew the budget; the stage's own failure is always reported as
/// `PipelineError::Stage`. Dropping this future (or the future that owns it)
/// drops the in-flight `stage.run` future, so no stage outlives its caller.
async fn run_stage(
    stage: &Stage,
    name: StageName,
    budget: &Budget,
) -> Result<Artifact, PipelineError> {
    let remaining = budget.remaining().ok_or(PipelineError::Deadline)?;
    timeout(remaining, stage.run(name))
        .await
        .map_err(|_| PipelineError::Deadline)?
        .map_err(|_| PipelineError::Stage { name })
}

pub async fn solve(
    stage: Stage,
    deadline: Duration,
) -> Result<Published, PipelineError> {
    let budget = Budget::new(deadline);

    // Both fetches race concurrently. `try_join` runs both; the first failure
    // is returned and the other fetch future is dropped, so nothing keeps
    // running once this future is dropped or resolves.
    let (a, b) = try_join(
        run_stage(&stage, StageName::FetchA, &budget),
        run_stage(&stage, StageName::FetchB, &budget),
    )
    .await?;

    // Combine is only reached when both fetches succeeded.
    let combined = run_stage(&stage, StageName::Combine, &budget).await?;

    // Fetch artifacts are no longer needed; release them explicitly before
    // publish runs.
    drop(a);
    drop(b);

    let published = run_stage(&stage, StageName::Publish, &budget).await?;
    drop(combined);

    Ok(Published::from(published))
}

//! A four-stage pipeline: `fetch_a` and `fetch_b` run concurrently, `combine`
//! waits for both, `publish` waits for `combine`.
//!
//! Resource discipline:
//! - There is no `spawn` anywhere. Every stage future is owned by the future
//!   returned from `solve`, so dropping that future — by the caller or by the
//!   deadline timer — drops every in-flight stage. No stage outlives `solve`.
//! - `try_join` drops the sibling fetch future on the first error, so a failed
//!   `fetch_a` immediately tears down the still-running `fetch_b` rather than
//!   leaving it live.
//! - Every fallible `Stage::run` call has its own explicit error mapping; no
//!   implicit `?` from `StageError` escapes.

use std::time::Duration;

use ai_task_support::{Published, Stage, StageError, StageName};
use futures::TryFutureExt;
use futures::future::try_join;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

/// Build the error mapping for one stage: any `StageError` from `name` becomes
/// `PipelineError::Stage { name }`, so the failure is always attributed to the
/// stage that actually produced it.
fn stage_err(name: StageName) -> impl FnOnce(StageError) -> PipelineError {
    move |_err| PipelineError::Stage { name }
}

/// The pipeline proper, with no deadline of its own. It is a plain future, so
/// dropping it drops the fetches, the combine, or the publish that is live.
async fn run_pipeline(stage: Stage) -> Result<Published, PipelineError> {
    // Fetches are independent: both are polled on this task, concurrently.
    // On the first failure try_join returns it and drops the other fetch.
    let (a, b) = try_join(
        stage.run(StageName::FetchA).map_err(stage_err(StageName::FetchA)),
        stage.run(StageName::FetchB).map_err(stage_err(StageName::FetchB)),
    )
    .await?;

    // Both fetches succeeded, so `combine` is now allowed to run. Read the
    // inputs here so the artifacts cannot be collected early.
    let _inputs = (a.value(), b.value());

    let _combined = stage
        .run(StageName::Combine)
        .await
        .map_err(stage_err(StageName::Combine))?;

    let published = stage
        .run(StageName::Publish)
        .await
        .map_err(stage_err(StageName::Publish))?;

    Ok(Published::from(published))
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    // `timeout` owns the pipeline future. On elapse it reports `Elapsed` and
    // drops that future, which drops the live stage with it, so no later stage
    // is started and none is left running.
    match timeout(deadline, run_pipeline(stage)).await {
        Ok(result) => result,
        Err(_elapsed) => Err(PipelineError::Deadline),
    }
}

