//! Bounded, cancellation-safe pipeline over the harness stages.
//!
//! `fetch_a` and `fetch_b` run concurrently; `combine` runs only after both
//! succeed; `publish` runs only after `combine`. The whole chain is bounded by
//! one overall deadline, and nothing is spawned: everything is awaited on the
//! task that awaits `solve`, so dropping the returned future stops all work.

use std::time::{Duration, Instant};

use ai_task_support::{Artifact, Published, Stage, StageName};
use futures::future::try_join;

/// Everything that can go wrong while running the pipeline.
#[derive(Debug)]
pub enum PipelineError {
    /// A stage returned an error. `name` is the stage that failed.
    Stage { name: StageName },
    /// The overall deadline elapsed before the pipeline finished.
    Deadline,
    /// The caller dropped the pipeline future mid-run.
    Cancelled,
}

/// A single absolute instant the whole pipeline is bounded by.
struct Deadline {
    at: Instant,
}

impl Deadline {
    fn new(limit: Duration) -> Self {
        Deadline {
            at: Instant::now() + limit,
        }
    }

    /// Time left, or `None` if the deadline has already passed.
    fn remaining(&self) -> Option<Duration> {
        let now = Instant::now();
        if now >= self.at {
            None
        } else {
            Some(self.at - now)
        }
    }
}

/// Run one stage under the remaining time.
///
/// `name` is taken as a constructor so a fresh `StageName` can be produced for
/// the error path without relying on `Copy`/`Clone` being in scope here.
async fn run_stage(
    stage: &Stage,
    name: impl Fn() -> StageName,
    deadline: &Deadline,
) -> Result<Artifact, PipelineError> {
    let remaining = deadline.remaining().ok_or(PipelineError::Deadline)?;
    match lgwks_bot::rt::time::timeout(remaining, stage.run(name())).await {
        Ok(Ok(artifact)) => Ok(artifact),
        Ok(Err(_)) => Err(PipelineError::Stage { name: name() }),
        Err(_) => Err(PipelineError::Deadline),
    }
}

/// Run the pipeline to completion within `deadline`.
pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let deadline = Deadline::new(deadline);

    // Independent fetches, run concurrently. On the first error the other
    // future is dropped, so no fetch outlives this point.
    let (a, b) = try_join(
        run_stage(&stage, || StageName::FetchA, &deadline),
        run_stage(&stage, || StageName::FetchB, &deadline),
    )
    .await?;

    // Both fetches succeeded; the artifacts feed the subsequent stages.
    drop((a, b));

    run_stage(&stage, || StageName::Combine, &deadline).await?;
    let published = run_stage(&stage, || StageName::Publish, &deadline).await?;

    Ok(Published::from(published))
}

use futures::future::try_join;
use lgwks_bot::rt::time::timeout;
use std::time::Duration;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: ai_task_support::StageName },
    Deadline,
    Cancelled,
}

async fn fetch_a(
    stage: &ai_task_support::Stage,
) -> Result<ai_task_support::Artifact, PipelineError> {
    stage
        .run(ai_task_support::StageName::FetchA)
        .await
        .map_err(|_| PipelineError::Stage {
            name: ai_task_support::StageName::FetchA,
        })
}

async fn fetch_b(
    stage: &ai_task_support::Stage,
) -> Result<ai_task_support::Artifact, PipelineError> {
    stage
        .run(ai_task_support::StageName::FetchB)
        .await
        .map_err(|_| PipelineError::Stage {
            name: ai_task_support::StageName::FetchB,
        })
}

pub async fn solve(
    stage: ai_task_support::Stage,
    deadline: Duration,
) -> Result<ai_task_support::Published, PipelineError> {
    let pipeline = async {
        let (_a, _b) = try_join(fetch_a(&stage), fetch_b(&stage)).await?;

        let combined = stage
            .run(ai_task_support::StageName::Combine)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Combine,
            })?;

        let published = stage
            .run(ai_task_support::StageName::Publish)
            .await
            .map_err(|_| PipelineError::Stage {
                name: ai_task_support::StageName::Publish,
            })?;

        Ok(ai_task_support::Published::from(combined))
    };

    match timeout(deadline, pipeline).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use futures::TryFutureExt;
use futures::future::try_join;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

fn tag(name: StageName) -> impl Fn(ai_task_support::StageError) -> PipelineError {
    move |_| PipelineError::Stage { name }
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let work = async {
        // fetch_a and fetch_b are independent: run both, and on the first
        // failure the other branch is dropped and combine never starts.
        let (_a, _b) = try_join(
            stage.run(StageName::FetchA).map_err(tag(StageName::FetchA)),
            stage.run(StageName::FetchB).map_err(tag(StageName::FetchB)),
        )
        .await?;

        let _combined = stage
            .run(StageName::Combine)
            .map_err(tag(StageName::Combine))
            .await?;

        let published: Artifact = stage
            .run(StageName::Publish)
            .map_err(tag(StageName::Publish))
            .await?;

        Ok(Published::from(published))
    };

    // `timeout` owns `work` by value: if the deadline elapses it drops the
    // pipeline future (cancelling the in-flight stage), and if the caller drops
    // this future, `timeout` drops `work` too, so no stage outlives the call.
    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::{Artifact, Published, Stage, StageName};
use futures::future;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum PipelineError {
    Stage { name: StageName },
    Deadline,
    Cancelled,
}

async fn run_named(
    stage: &Stage,
    name: StageName,
) -> Result<Artifact, PipelineError> {
    stage
        .run(name)
        .await
        .map_err(|_| PipelineError::Stage { name })
}

pub async fn solve(stage: Stage, deadline: Duration) -> Result<Published, PipelineError> {
    let pipeline = async {
        // Both fetches are independent: `try_join` runs them concurrently and,
        // on the first failure, returns that error and drops the sibling, so
        // nothing is left running once we bail out.
        let (_a, _b) = future::try_join(
            run_named(&stage, StageName::FetchA),
            run_named(&stage, StageName::FetchB),
        )
        .await?;

        // `?` above guarantees neither of these runs unless both fetches won.
        let _combined = run_named(&stage, StageName::Combine).await?;

        run_named(&stage, StageName::Publish)
            .await
            .map(Published::from)
    };

    // The single timer covers the whole pipeline; the stages are awaited
    // sequentially inside `pipeline`, so an elapsed deadline cannot leave a
    // later stage pending, and dropping `pipeline` on timeout (or on caller
    // cancellation) drops the in-flight stage future with it. Nothing here is
    // spawned, so cancellation stops the work too.
    match timeout(deadline, pipeline).await {
        Ok(result) => result,
        Err(_) => Err(PipelineError::Deadline),
    }
}
